import {normaliseJob,httpLink,remoteMode,ukEligibility} from './normalization.mjs';
function decode(s=''){return String(s).replace(/^<!\[CDATA\[([\s\S]*?)\]\]>$/,'$1').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'");}
export function parseSimpleRSS(xml){if(typeof xml!=='string'||xml.length>2000000||!/<(?:rss|rdf:RDF)\b/i.test(xml))throw new Error('Unsupported RSS feed');const items=xml.match(/<item\b[^>]*>[\s\S]*?<\/item>/gi)||[];const tag=(s,key)=>decode((s.match(new RegExp('<(?:[\\w-]+:)?'+key+'\\b[^>]*>([\\s\\S]*?)<\\/(?:[\\w-]+:)?'+key+'>','i'))||[])[1]||'');return items.slice(0,500).map(s=>({guid:tag(s,'guid'),title:tag(s,'title'),link:tag(s,'link'),description:tag(s,'description'),pubDate:tag(s,'pubDate')}));}
export function createRSSSource({id,url,attribution,mapItem,fetchFn=fetch,parse=parseSimpleRSS}){if(!/^[a-z0-9_-]+$/.test(id)||!httpLink(url))throw new Error('RSS adapter configuration is invalid');if(typeof mapItem!=='function')throw new Error('RSS adapter requires an explicit field mapping');return {id,kind:'rss',attribution,async fetchPage(){const res=await fetchFn(url,{headers:{Accept:'application/rss+xml, application/xml'},signal:AbortSignal.timeout(12000)});if(!res.ok)throw new Error(`${id} RSS HTTP ${res.status}`);const xml=await res.text(),rawItems=parse(xml);return {jobs:rawItems.map(item=>{const v=mapItem(item);return normaliseJob({...v,provider:id,source_id:String(v.source_id||item.guid||item.link),remote_mode:v.remote_mode||remoteMode(v.title,v.description,false),uk_eligibility:v.uk_eligibility||ukEligibility(v.location,v.description)});}),nextCursor:null,hasMore:false};}};}
